 write('NativeMenuTest.java','import com.chance.bitlifediag.*;import java.util.*;\npublic class NativeMenuTest {\n static int checks;static void ck(boolean b,String s){checks++;if(!b)throw new AssertionError(s+" "+Arrays.toString(MilitaryBridge.fields));}\n static void open(int a){NativeMilitary.prepare(a);ck(MilitaryBridge.fields!=null&&MilitaryBridge.fields.length==8,"eight native fields");for(int i=0;i<(MilitaryBridge.kind&7);i++)ck(!MilitaryBridge.fields[4+i].isEmpty()&&!MilitaryBridge.fields[4+i].startsWith("scenario."),"visible player-facing choice");}\n static void choose(String label){for(int page=0;page<16;page++){int n=MilitaryBridge.kind&7;for(int i=0;i<n;i++)if(MilitaryBridge.fields[4+i].equals(label)){open(100+i);return;}boolean more=false;for(int i=0;i<n;i++)if(MilitaryBridge.fields[4+i].equals("More choices")){open(100+i);more=true;break;}if(!more)break;}throw new AssertionError("Absent choice: "+label);}\n static MilitaryModel.State state(){return new MilitaryModel.State(MilitaryBridge.texts[8]);}\n static void person(String c,String city,int year,int age){NativeMilitary.close();MilitaryBridge.texts[8]="";MilitaryBridge.texts[9]="";MilitaryBridge.texts[0]="Alex";MilitaryBridge.texts[1]=c;MilitaryBridge.texts[3]=city;MilitaryBridge.ints[4]++;MilitaryBridge.ints[8]=year;MilitaryBridge.ints[9]=age;MilitaryBridge.ints[11]=0;MilitaryBridge.ints[12]=85;MilitaryBridge.ints[13]=80;MilitaryBridge.ints[25]=0;}\n public static void main(String[] args){NativeMilitary.attach(new android.content.Context());\n person("United Kingdom","London",1940,25);open(10);choose("Register for national service");ck(!MilitaryBridge.journal.isEmpty()&&state().i("stage",0)==1,"registration saves and explains next step");MilitaryBridge.ints[8]=1941;MilitaryBridge.ints[9]=26;open(10);ck(state().i("stage",0)==2,"manual opening advances call-up without broken HUD detection");choose("Report for medical assessment");ck(MilitaryBridge.fields[1].equals("Service update"),"medical result popup");choose("Continue");choose("Accept induction — replace my civilian job");ck(MilitaryBridge.effect==2,"induction emits real native employment command");MilitaryBridge.ints[11]=1;MilitaryBridge.ints[8]=1942;MilitaryBridge.ints[9]=27;open(12);ck(state().i("stage",0)==6,"native employment and elapsed training year connected");choose("Practise aircrew");choose("Continue");choose("Practise aircrew");choose("Continue");choose("Request aircrew assignment");ck(state().s("role").equals("Aircrew"),"aircrew training gives actual saved role");\n open(13);choose("Aircraft reconnaissance");choose("Continue");choose("Check conditions with the crew");choose("Continue");choose("Observe from the clear route");choose("Continue");choose("Return together on the safer route");ck(state().i("missions",0)==1&&MilitaryBridge.fields[1].equals("Unit report"),"three-round flight ends in saved unit report");\n open(16);choose("Move a piece");choose("pawn · e2");choose("e4");choose("Opponent\'s move");ck(new MilitaryModel.State(MilitaryBridge.texts[9]).s("moves").split(" ").length==2,"existing legal chess rules and saved moves retained");\n person("Germany","Berlin",1939,25);MilitaryBridge.ints[25]=1;open(10);ck(state().i("stage",0)==2,"actual annual German draft notice opens medical stage");choose("Report for medical assessment");ck(state().i("stage",0)==3,"new jurisdiction medical assessment");\n for(String country:new String[]{"Germany","France","Canada","New Zealand","Russia","Japan","Italy","India","Australia","United States","United Kingdom"}){MilitaryModel.State st=new MilitaryModel.State("");st.put("jurisdiction",country);MilitaryModel.Eligibility e=MilitaryModel.eligibility(new MilitaryModel.Person(1942,25,0,80,70,country,"Capital",false,true),st);ck(e.supported&&e.volunteer,"supported recruitment "+country);ck(!e.reason.isEmpty(),"country-specific explanation "+country);}\n MilitaryModel.State uk=new MilitaryModel.State("");uk.put("jurisdiction","United Kingdom");ck(!MilitaryModel.eligibility(new MilitaryModel.Person(1942,25,0,80,70,"United Kingdom","Belfast",false,true),uk).draft,"Northern Ireland excluded from automatic draft");\n MilitaryModel.State au=new MilitaryModel.State("");au.put("jurisdiction","Australia");ck(!MilitaryModel.eligibility(new MilitaryModel.Person(1916,25,0,80,70,"Australia","Sydney",false,true),au).draft,"Australian WWI overseas service stays voluntary");\n person("United States","Miami",2026,0);open(10);ck(!MilitaryBridge.fields[2].contains("Report for your medical")&&state().i("stage",0)==0,"modern infant never called up");\n System.out.println("{\\"passed\\":true,\\"checks\\":"+checks+",\\"host_JVM\\":true,\\"JNI_and_graphics_modeled\\":true,\\"ART_tested\\":false}");}\n}')
